import{_ as e,c as s,a0 as n,o as t}from"./chunks/framework.iBbVlLT2.js";const m=JSON.parse('{"title":"CLI","description":"","frontmatter":{},"headers":[],"relativePath":"introduction/cli.md","filePath":"introduction/cli.md"}'),p={name:"introduction/cli.md"};function o(l,a,i,d,r,c){return t(),s("div",null,a[0]||(a[0]=[n(`<h1 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h1><p>Mugo accepts templates and data from command-line values, files, URLs, or standard input.</p><p>The positional argument or standard input is treated as the template by default. When <code>--template</code> is set, that value is the template and the positional argument or standard input is treated as data. <code>--data</code> supplies data explicitly; when both <code>--template</code> and <code>--data</code> are set, positional and standard input data are ignored.</p><p>Prefix a <code>--data</code> or <code>--template</code> value with <code>@</code> to load it from a local file. Use <code>--no-at</code> when a literal value must begin with <code>@</code>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki dracula vp-code" tabindex="0"><code><span class="line"><span>Usage:</span></span>
<span class="line"><span>  mugo &lt;template&gt; [flags]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Examples:</span></span>
<span class="line"><span>mugo -d @data.yaml template.tpl</span></span>
<span class="line"><span>mugo -d &#39;{&quot;Name&quot;: &quot;mugo&quot;}&#39; -o output.txt template.tpl</span></span>
<span class="line"><span>mugo -d &#39;{&quot;Name&quot;: &quot;mugo&quot;}&#39; -o output.txt - &lt; template.tpl</span></span>
<span class="line"><span>mugo -d &#39;{&quot;Name&quot;: &quot;mugo&quot;}&#39; - &lt;&lt;&lt; &quot;{{.Name}}&quot;</span></span>
<span class="line"><span>mugo -d &#39;{&quot;Name&quot;: &quot;mugo&quot;}&#39; -t @template.tpl</span></span>
<span class="line"><span>mugo -t &#39;{{.Name}}&#39; data.yaml</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Flags:</span></span>
<span class="line"><span>  -d, --data stringArray            input data as json/yaml or file path with @ prefix could be &#39;.yaml&#39;,&#39;.yml&#39;,&#39;.json&#39;,&#39;.toml&#39; extension</span></span>
<span class="line"><span>  -r, --data-raw                    set input data as raw</span></span>
<span class="line"><span>  -b, --data-raw-byte               raw data is byte</span></span>
<span class="line"><span>      --delims string               comma or space separated list of delimiters to alternate the default &quot;{{ }}&quot;</span></span>
<span class="line"><span>      --disable-func stringArray    disabled functions for run template</span></span>
<span class="line"><span>      --disable-group stringArray   disabled groups for run template</span></span>
<span class="line"><span>      --enable-func stringArray     specific functions for run template</span></span>
<span class="line"><span>      --enable-group stringArray    specific function groups for run template</span></span>
<span class="line"><span>  -h, --help                        help for mugo</span></span>
<span class="line"><span>      --html                        use html/template instead</span></span>
<span class="line"><span>  -k, --insecure                    skip verify ssl certificate</span></span>
<span class="line"><span>  -l, --list                        function list</span></span>
<span class="line"><span>      --log-level string            log level (debug, info, warn, error), default is info (default &quot;info&quot;)</span></span>
<span class="line"><span>      --no-at                       disable @ prefix for file path</span></span>
<span class="line"><span>      --no-retry                    disable retry on request</span></span>
<span class="line"><span>  -n, --no-stdin                    disable stdin input</span></span>
<span class="line"><span>  -o, --output string               output file, default is stdout</span></span>
<span class="line"><span>  -p, --parse stringArray           parse file pattern for define templates &#39;testdata/**/*.tpl&#39;</span></span>
<span class="line"><span>      --perm-file string            create file permission, default is 0644</span></span>
<span class="line"><span>      --perm-folder string          create folder permission, default is 0755</span></span>
<span class="line"><span>      --random-seed int             seed for random function, default is 0 (random by time)</span></span>
<span class="line"><span>  -s, --silience                    silence log output</span></span>
<span class="line"><span>  -t, --template string             input template as raw or file path with @ prefix could be file with any extension</span></span>
<span class="line"><span>      --trust                       trust to execute dangerous functions</span></span>
<span class="line"><span>  -v, --version                     version for mugo</span></span>
<span class="line"><span>  -w, --work-dir string             work directory for run template</span></span></code></pre></div><h2 id="input-data" tabindex="-1">Input data <a class="header-anchor" href="#input-data" aria-label="Permalink to &quot;Input data&quot;">​</a></h2><p>Without <code>--data-raw</code>, inline data is decoded as YAML. JSON is valid YAML, so both formats can be passed directly. Files loaded with the <code>@</code> prefix support <code>.json</code>, <code>.yaml</code>, <code>.yml</code>, and <code>.toml</code> extensions.</p><p>Use <code>--data-raw</code> to pass data as a string. Add <code>--data-raw-byte</code> to expose file or input data as <code>[]byte</code> instead.</p><p>Multiple <code>--data</code> flags are merged in the order supplied.</p><h2 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h2><p>The positional template may be a local file, an HTTP(S) URL, or <code>-</code> for standard input. <code>--parse</code> may be repeated to parse additional template definitions before executing the main template.</p><p>Use <code>--html</code> to switch from <code>text/template</code> to <code>html/template</code>, and <code>--delims &#39;&lt;% %&gt;&#39;</code> to set custom left and right delimiters.</p><h2 id="output-and-security" tabindex="-1">Output and security <a class="header-anchor" href="#output-and-security" aria-label="Permalink to &quot;Output and security&quot;">​</a></h2><p>Rendered output is written to standard output unless <code>--output</code> is set. <code>--perm-folder</code> and <code>--perm-file</code> control permissions for newly created output paths.</p><p>Functions that execute commands or write files require <code>--trust</code>. Keep trust disabled for untrusted templates.</p><p>The silence flag is currently spelled <code>--silience</code> for CLI compatibility; <code>-s</code> is the recommended shorthand.</p>`,16)]))}const f=e(p,[["render",o]]);export{m as __pageData,f as default};
